# KN7000 "Program" flash image, build 893 (firmware v1.3) - byte-exact.
# Panasonic MN10300, mapped at CPU 0x48400000. GENERATED by
# `tools/gen_program_s.py --profile b893` (make program-src-893) -- do not
# edit by hand.
#
# Build 893 is the program flash of Felipe's own instrument (v1.3), two
# releases before 941. It is ported from build 941 like build 935 (see
# notes/older-program-builds.md): names, the function split, FUNC_END caps,
# data islands, library ranges and notes come through the exact 941->893
# offset map where it places them 1:1 (kn7000_b893*.sym); routines the
# map cannot place take a 941 name only where tools/port_names_by_code.py
# finds the same code (kn7000_b893_bycode.sym). CPU addresses quoted in
# the notes are translated to build 893; "build-941 0x..." marks one that
# has no counterpart. make verify-893 guarantees byte-identity.
#
# Labels in converted code: a function keeps its symbol-file name (an
# `X_entry` label is the register-save `call` entry a few bytes after the
# `movm` / `add -N, sp` prologue of X); func_<ADDR> is a function no symbol
# file names yet (a call target, a pointer to a prologue, or the code after a
# FUNC_END cap), its call entry func_<ADDR>_entry; loc_<ADDR> a branch
# target or code address inside a function, rodata_<ADDR> typed data. A
# symbol-file name that sits on the call entry itself keeps that address: its
# block header then says where the unlabelled prologue in front of it starts.

.equ PROGRAM_ROM_BASE, 0x48400000
.mnbase 0x48400000   # CPU address of output offset 0 (for PC-relative ops)
.include "src/b893/symbols.inc"
.include "src/b893/program/data/gui_event_ids.inc"   # EV_ / MT_ ids, named in mov / cmp immediates
.include "src/b893/program/data/gui_code_ids.inc"   # TT_ / MD_ / CLASS_ / FN_ / object ids, likewise

# 2 names converted code references outside itself (not in symbols.inc)
.equ TableRomDirectory, 0x48000000
.equ LibRomImageBase, 0x487B76B1

# 11 data addresses named by annotations/*.ann
.equ DrawIcons_PixelPairTable, 0x485A0FBC   # 256 x u16: icon byte -> {left, right} palette index (nibble n -> n, or 0xF0+n if n >= 8)
.equ Pixel4bppPairTable, 0x485A11BC   # u16[256]: byte -> two pixels {lo: 0x20 + high nibble, hi: 0x20 + low nibble}
.equ BmpSignature, 0x485A15BC   # "BM", NUL-terminated: the BMP bfType GetBitmapInfo compares
.equ RoundCornerPixels, 0x485A15C0   # 8 x {u16 dx, u16 dy}: the pixels a DrawJpegFileR corner keeps
.equ SjisMissingGlyph, 0x485A15E0   # 16x16 1 bpp column-major glyph: a box with an X in it
.equ DrawEnable, 0x5002A018   # nonzero: drawing allowed (tested before every DrawXxx_Impl)
.equ FrameBuffer, 0x500D405C   # 640 x 240 x 8 bpp, stride 0x280
.equ BitmapTablePtr, 0x50122D88   # -> bitmap descriptors {s16 w, s16 h, u8 *pixels}
.equ FrameTablePtr, 0x50122D8C   # -> frame-piece descriptors {s16 w, s16 h, u8 *pixels}
.equ IconTablePtr, 0x50122D90   # -> icon descriptors {s16 w, s16 h, u8 *pixels}
.equ FontTablePtr, 0x50122D94   # -> 0x14-byte font descriptors

# ---- boot header (0x0..0x80) ----
_reset:
    jmp     ResetEntry
    nop
    nop
    nop
    nop
    nop
_vector_08:
    jmp     func_484D75C2
    .space 2, 0xFF
_rom_marker:
    .byte 0x13                              # firmware release v1.3 (shown by the boot ROM as NOW(CURRENT))
    .space 0x80 - 0x10, 0xFF
    .org 0x000080

